-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.release_neutral_fields(occlusion boolean)
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select case when occlusion
    -- In an occlusion, the image IS the question (its labels are what is hidden).
    then array['Reverso extra', 'Comentarios', 'Código', 'Creación', 'Actualización']
    else array['Extra', 'Imagen', 'Tema', 'Fuente', 'Código', 'Creación', 'Actualización']
  end;
$function$;
